function helper(title,paragraph,action='',reference=''){return `<div class="guide"><div class="guide-head"><span>📘 ${esc(title)}</span>${reference?`<small dir="ltr">Trost 2014 · ${esc(reference)}</small>`:''}</div><p>${esc(paragraph)}</p>${action}</div>`}
function pillChoice(name,values,selected='',required=false){return `<div class="choice-row">${Object.entries(values).map(([v,k])=>`<label class="pill-choice"><input type="radio" name="${esc(name)}" value="${esc(v)}" ${String(selected)===v?'checked':''} ${required?'required':''}><span>${esc(k)}</span></label>`).join('')}</div>`}
function choiceSelect(name,label,options,current=''){return `<div class="formgroup"><label>${esc(label)}</label><select name="${esc(name)}" ${!current?'':' '}>${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${k===current?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`}
function roleExampleGallery(){let cards=ROLE_EXAMPLES.map(p=>`<button type="button" class="example-card" data-action="use-role-example" data-id="${p.id}"><span class="chip">${esc(choose(SECTORS,p.sector))}</span><b>${esc(p.name)}</b><span>${esc(p.why)}</span><small>انتخاب و ویرایش مثال ←</small></button>`).join('');overlay('نمونه‌های نقش کلیدی و گلوگاهی',`<p class="muted">نمونه‌ها صرفاً برای شروع تحلیل‌اند؛ امتیازها و مفروضات بازار باید با داده سازمان شما تأیید شوند. Trost، فصل ۴.</p><div class="example-grid">${cards}</div>`)}
