 overlay(uid?'ویرایش فرصت استخدام':'ایجاد فرصت استخدام',`<form data-form="vacancy" data-id="${esc(uid||'')}" class="forms">${sel('roleId','نقش مرتبط',opts(db.roles,'name'),v.roleId||db.roles[0].id,'انتخاب نقش')}${txt('reason','چرا اکنون این موقعیت باید تأمین شود؟',v.reason||'','جایگزینی، رشد کسب‌وکار، نقش جدید یا ریسک تداوم')}${inp('owner','مسئول جذب',v.owner||'','text','required maxlength="120"')}<div class="formrow">${sel('status','مرحله',statuses,v.status||'open','')}${inp('deadline','زمان هدف',v.deadline||'','date')}</div>${txt('notes','محدودیت‌ها و توافق‌های مدیر واحد',v.notes||'')}${modalFoot()}</form>`);
