function cloudAgentPanel(){
 const client=window.TRMCloudAgent,st=client?.status?.();
 if(!st?.configured)return '<div class="coach-disclosure">AI Agent مولد به زیرساخت سازمانی اختصاصی متصل نشده است. تحلیلگر محلی فعلاً قابل استفاده است.</div>';
 if(!st.signedIn)return `<div class="panel cloud-panel"><h3>ورود به AI Agent سازمانی</h3><form class="forms" data-form="cloud-login">
 ${inp('email','ایمیل سازمانی','','email','required autocomplete="username"')}
 ${inp('password','گذرواژه','','password','required autocomplete="current-password"')}
 <button class="btn" type="submit">ورود امن</button></form><p class="smalltext muted">رمز عبور در اپ ذخیره نمی‌شود؛ اتصال از Supabase Auth اختصاصی TRM استفاده می‌کند.</p></div>`;
 if(!st.orgId)return `<div class="panel cloud-panel"><h3>انتخاب سازمان</h3><div class="formgroup"><label for="cloud-org">فضای سازمانی</label><select id="cloud-org"><option value="">انتخاب کنید</option>${st.organizations.map(x=>`<option value="${esc(x.org_id)}">${esc(x.org_id)} · ${esc(x.role)}</option>`).join('')}</select></div><button class="btn secondary small" data-action="cloud-logout">خروج</button></div>`;
 return `<div class="cloud-ready"><span class="chip alt">AI Agent متصل</span><span>پیشنهادهای مولد نیازمند تأیید شما هستند.</span><button class="btn ghost small" data-action="cloud-logout">خروج</button></div>`;
}
function cloudContext(mode,roleId,vacancyId){
 const r=db.roles.find(x=>x.id===roleId)||null;
 const e=db.evps.find(x=>x.roleId===roleId)||null;
 const v=db.vacancies.find(x=>x.id===vacancyId)||db.vacancies.find(x=>x.roleId===roleId)||null;
 const pick=(obj,fields)=>obj?Object.fromEntries(fields.map(([out,key])=>[out,String(obj[key]??'').slice(0,700)])):{};
 const role=pick(r,[['title','name'],['strategy','strategy'],['strategyEvidence','strategyEvidence'],['strategicImportance','strategic'],['marketAvailability','availability'],['forecastDemand','demand'],['targetGroup','targetGroup'],['criticalIncidents','challenges'],['acceptableGaps','gap'],['marketEvidence','marketEvidence']]);
 const evp=pick(e,[['strengths','strengths'],['preferences','preferences'],['competition','competition'],['difference','difference'],['proof','proof']]);
 const vacancy=pick(v,[['reason','reason'],['status','status'],['deadline','deadline']]);
 const related=db.people.filter(x=>x.roleId===roleId);
 const metrics={relatedPoolCount:related.length,contactableWithOptInCount:related.filter(x=>x.consent==='yes'&&x.readiness!=='no').length,
  noContactCount:related.filter(x=>x.consent!=='yes').length,openFollowups:db.activities.filter(x=>x.state!=='done'&&x.nextDate&&x.nextDate<=dateNow()).length};
 return {role,evp,vacancy,metrics};
}
async function runCloudCoach(){
 const form=el('#coach-form');if(!form)return;
 const mode=form.querySelector('#coach-mode').value,roleId=form.querySelector('#coach-role').value,vacancyId=form.querySelector('#coach-vacancy').value;
 const question=trim(form.querySelector('#coach-question')?.value||'');
 if(!confirm('برای تحلیل AI فقط اطلاعات ساختاری نقش، EVP و شمارش تجمیعی Talent Pool به سرویس اختصاصی ارسال می‌شود. اطلاعات شخصی یا محرمانه داخل فیلدها نگذارید. ادامه می‌دهید؟'))return;
 const action=el('[data-action="run-cloud-coach"]');if(action){action.disabled=true;action.textContent='در حال تحلیل…'}
 try{
  const data=await window.TRMCloudAgent.analyze(mode,cloudContext(mode,roleId,vacancyId),question);
  const r={actionObjects:Array.isArray(data.actions)?data.actions:[],title:'تحلیل پیشنهادی AI Agent',readiness:'پیش‌نویس مولد · تأیید انسانی لازم است',summary:String(data.summary||''),
   missing:Array.isArray(data.missingEvidence)?data.missingEvidence:[],draft:String(data.draft||''),
   steps:(data.actions||[]).map(x=>[x.title,x.why,x.evidence?'شاهد لازم: '+x.evidence:'',x.ownerHint?'مسئول پیشنهادی: '+x.ownerHint:'',Number.isInteger(x.targetDays)?'افق پیشنهادی: '+x.targetDays+' روز':''].filter(Boolean).join(' — ')),
   source:(data.bookBasis||[]).join(' · ')||'Trost (2014)',caveats:data.caveats||[]};
  ui.lastCoachResult=r;const analysisId=id();ui.lastAnalysisId=analysisId;
  const box=el('#coach-result');if(box)box.innerHTML=coachResultHTML(r)+(r.caveats?.length?'<p class="smalltext muted">محدودیت‌ها: '+esc(r.caveats.join('؛ '))+'</p>':'');
  db.analyses.unshift({id:analysisId,mode:'generative:'+mode,roleId,vacancyId,result:r,createdAt:new Date().toISOString()});
  if(db.analyses.length>40)db.analyses.length=40;persist();
 }finally{if(action){action.disabled=false;action.textContent='✧ تحلیل مولد با AI'}}
}
async function cloudLogin(form){
 const email=trim(form.querySelector('[name="email"]')?.value),password=form.querySelector('[name="password"]')?.value;
 const b=form.querySelector('button[type="submit"]');if(b)b.disabled=true;
 try{const r=await window.TRMCloudAgent.signIn(email,password);render();toast(r.needsSelection?'سازمان را انتخاب کنید.':'ورود سازمانی تأیید شد.')}
 catch(e){toast(e.message||'ورود ناموفق بود.')}
 finally{if(b)b.disabled=false}
}

